CREATE OR REPLACE FUNCTION public.factory_freeze_authority_set(p_case_code text, p_case_canon_authority_id text, p_case_logic_authority_id text, p_production_state_authority_id text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  rc public.factory_authority_records%rowtype;
  rl public.factory_authority_records%rowtype;
  rp public.factory_authority_records%rowtype;
  v_match_count int;
begin
  perform pg_advisory_xact_lock(hashtext(p_case_code));

  rc := public.factory_get_ready_authority(p_case_canon_authority_id,p_case_code,'CASE_CANON','authoritative');
  rl := public.factory_get_ready_authority(p_case_logic_authority_id,p_case_code,'CASE_LOGIC','authoritative');
  rp := public.factory_get_ready_authority(p_production_state_authority_id,p_case_code,'PRODUCTION_STATE','authoritative');

  select count(*) into v_match_count
  from public.factory_authority_current c
  where c.case_code=p_case_code
    and ((c.authority_type='CASE_CANON' and c.authority_record_id=rc.id)
      or (c.authority_type='CASE_LOGIC' and c.authority_record_id=rl.id)
      or (c.authority_type='PRODUCTION_STATE' and c.authority_record_id=rp.id));
  if v_match_count <> 3 then raise exception 'AUTHORITY_SET_NOT_CURRENT'; end if;

  perform set_config('factory.authority_transition','on',true);

  update public.factory_authority_records
  set state='frozen', frozen_by=p_actor, frozen_at=now()
  where id in (rc.id,rl.id,rp.id);

  update public.factory_documents
  set is_authoritative=true, authority_state='frozen', updated_at=now()
  where document_key in (rc.source_document_key,rl.source_document_key,rp.source_document_key);

  perform public.factory_reconcile_case_authority(p_case_code);

  insert into public.factory_audit_log(actor,action,entity_type,entity_id,payload)
  values(
    p_actor,'AUTHORITY_SET_FROZEN','authority_set',p_case_code,
    jsonb_build_object(
      'case_code',p_case_code,
      'case_canon',p_case_canon_authority_id,
      'case_logic',p_case_logic_authority_id,
      'production_state',p_production_state_authority_id
    )
  );

  return jsonb_build_object(
    'case_code',p_case_code,
    'records',(
      select jsonb_agg(to_jsonb(r) order by r.authority_type)
      from public.factory_authority_records r
      where r.id in (rc.id,rl.id,rp.id)
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.factory_get_ready_authority(p_authority_id text, p_case_code text, p_authority_type text, p_required_state text)
 RETURNS factory_authority_records
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.factory_authority_records%rowtype;
  d public.factory_documents%rowtype;
  g public.factory_gate_records%rowtype;
begin
  select * into r
  from public.factory_authority_records
  where authority_id = p_authority_id
  for update;

  if not found then raise exception 'AUTHORITY_NOT_FOUND'; end if;
  if r.case_code is distinct from p_case_code then raise exception 'AUTHORITY_SET_CASE_MISMATCH'; end if;
  if r.authority_type is distinct from p_authority_type then raise exception 'AUTHORITY_SET_TYPE_MISMATCH'; end if;

  if p_required_state = 'validated' and r.state <> 'validated' then
    raise exception 'AUTHORITY_SET_NOT_VALIDATED';
  elsif p_required_state = 'authoritative' and r.state <> 'authoritative' then
    raise exception 'AUTHORITY_SET_NOT_AUTHORITATIVE';
  end if;

  if r.source_document_key is null then raise exception 'SOURCE_DOCUMENT_REQUIRED'; end if;
  select * into d from public.factory_documents where document_key=r.source_document_key;
  if not found or d.case_code is distinct from r.case_code or d.sha256 is distinct from r.sha256 then
    raise exception 'SOURCE_DOCUMENT_MISMATCH';
  end if;

  if r.supporting_gate_id is not null then
    select * into g from public.factory_gate_records where gate_id=r.supporting_gate_id;
    if not found or g.case_code is distinct from r.case_code or g.status <> 'pass' then
      raise exception 'SUPPORTING_GATE_NOT_PASS';
    end if;
  end if;

  return r;
end;
$function$

CREATE OR REPLACE FUNCTION public.factory_normalize_embedded_json_object(input_value jsonb, field_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  parsed jsonb;
begin
  if input_value is null then
    return '{}'::jsonb;
  end if;

  if jsonb_typeof(input_value) = 'object' then
    return input_value;
  end if;

  if jsonb_typeof(input_value) <> 'string' then
    raise exception '% must be a JSON object or a JSON-encoded object string', field_name;
  end if;

  begin
    parsed := (input_value #>> '{}')::jsonb;
  exception when others then
    raise exception '% contains invalid embedded JSON', field_name;
  end;

  if parsed is null or jsonb_typeof(parsed) <> 'object' then
    raise exception '% embedded JSON must decode to an object', field_name;
  end if;

  return parsed;
end;
$function$

CREATE OR REPLACE FUNCTION public.factory_normalize_handoff_payload()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.payload := public.factory_normalize_embedded_json_object(new.payload, 'payload');
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.factory_normalize_return_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.metadata := public.factory_normalize_embedded_json_object(new.metadata, 'metadata');
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.factory_preserve_authoritative_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_internal boolean := coalesce(current_setting('factory.authority_transition', true),'') = 'on';
begin
  if old.is_authoritative = true or old.authority_state in ('authoritative','frozen') then
    if new.sha256 is distinct from old.sha256 then
      raise exception 'AUTHORITATIVE_DOCUMENT_IMMUTABLE';
    end if;
    if not v_internal then
      new.is_authoritative := old.is_authoritative;
      new.authority_state := old.authority_state;
    else
      if new.authority_state not in ('authoritative','frozen','superseded') then
        raise exception 'INVALID_INTERNAL_AUTHORITY_TRANSITION';
      end if;
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.factory_promote_authority_set(p_case_code text, p_case_canon_authority_id text, p_case_logic_authority_id text, p_production_state_authority_id text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  rc public.factory_authority_records%rowtype;
  rl public.factory_authority_records%rowtype;
  rp public.factory_authority_records%rowtype;
  v_current_count int;
begin
  perform pg_advisory_xact_lock(hashtext(p_case_code));

  rc := public.factory_get_ready_authority(p_case_canon_authority_id,p_case_code,'CASE_CANON','validated');
  rl := public.factory_get_ready_authority(p_case_logic_authority_id,p_case_code,'CASE_LOGIC','validated');
  rp := public.factory_get_ready_authority(p_production_state_authority_id,p_case_code,'PRODUCTION_STATE','validated');

  select count(*) into v_current_count from public.factory_authority_current where case_code=p_case_code;
  if v_current_count <> 0 then raise exception 'CURRENT_AUTHORITY_NOT_EMPTY'; end if;

  perform set_config('factory.authority_transition','on',true);

  update public.factory_authority_records
  set state='authoritative', promoted_by=p_actor, promoted_at=now()
  where id in (rc.id,rl.id,rp.id);

  insert into public.factory_authority_current(case_code,authority_type,authority_record_id,updated_at)
  values
    (p_case_code,'CASE_CANON',rc.id,now()),
    (p_case_code,'CASE_LOGIC',rl.id,now()),
    (p_case_code,'PRODUCTION_STATE',rp.id,now());

  update public.factory_documents
  set is_authoritative=true, authority_state='authoritative', updated_at=now()
  where document_key in (rc.source_document_key,rl.source_document_key,rp.source_document_key);

  perform public.factory_reconcile_case_authority(p_case_code);

  insert into public.factory_audit_log(actor,action,entity_type,entity_id,payload)
  values(
    p_actor,'AUTHORITY_SET_PROMOTED','authority_set',p_case_code,
    jsonb_build_object(
      'case_code',p_case_code,
      'case_canon',p_case_canon_authority_id,
      'case_logic',p_case_logic_authority_id,
      'production_state',p_production_state_authority_id
    )
  );

  return jsonb_build_object(
    'case_code',p_case_code,
    'records',(
      select jsonb_agg(to_jsonb(r) order by r.authority_type)
      from public.factory_authority_records r
      where r.id in (rc.id,rl.id,rp.id)
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.factory_replace_authority_set(p_case_code text, p_case_canon_authority_id text, p_case_logic_authority_id text, p_production_state_authority_id text, p_actor text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  rc public.factory_authority_records%rowtype;
  rl public.factory_authority_records%rowtype;
  rp public.factory_authority_records%rowtype;
  old_ids uuid[];
  old_count int;
begin
  if p_reason is null or length(trim(p_reason)) < 3 then raise exception 'REPLACEMENT_REASON_REQUIRED'; end if;
  perform pg_advisory_xact_lock(hashtext(p_case_code));

  rc := public.factory_get_ready_authority(p_case_canon_authority_id,p_case_code,'CASE_CANON','validated');
  rl := public.factory_get_ready_authority(p_case_logic_authority_id,p_case_code,'CASE_LOGIC','validated');
  rp := public.factory_get_ready_authority(p_production_state_authority_id,p_case_code,'PRODUCTION_STATE','validated');

  select array_agg(authority_record_id order by authority_type), count(*)
  into old_ids, old_count
  from public.factory_authority_current
  where case_code=p_case_code;
  if old_count <> 3 then raise exception 'CURRENT_AUTHORITY_SET_INCOMPLETE'; end if;

  if exists(
    select 1 from public.factory_authority_records r
    where r.id = any(old_ids) and r.state not in ('authoritative','frozen')
  ) then raise exception 'CURRENT_AUTHORITY_SET_INVALID'; end if;

  perform set_config('factory.authority_transition','on',true);

  update public.factory_documents d
  set is_authoritative=false, authority_state='superseded', updated_at=now()
  where d.document_key in (
    select r.source_document_key from public.factory_authority_records r where r.id = any(old_ids)
  );

  update public.factory_authority_records
  set state='superseded', superseded_by=p_actor, superseded_at=now(), supersede_reason=trim(p_reason)
  where id = any(old_ids);

  delete from public.factory_authority_current where case_code=p_case_code;

  update public.factory_authority_records
  set state='authoritative', promoted_by=p_actor, promoted_at=now()
  where id in (rc.id,rl.id,rp.id);

  insert into public.factory_authority_current(case_code,authority_type,authority_record_id,updated_at)
  values
    (p_case_code,'CASE_CANON',rc.id,now()),
    (p_case_code,'CASE_LOGIC',rl.id,now()),
    (p_case_code,'PRODUCTION_STATE',rp.id,now());

  update public.factory_documents
  set is_authoritative=true, authority_state='authoritative', updated_at=now()
  where document_key in (rc.source_document_key,rl.source_document_key,rp.source_document_key);

  perform public.factory_reconcile_case_authority(p_case_code);

  insert into public.factory_audit_log(actor,action,entity_type,entity_id,payload)
  values(
    p_actor,'AUTHORITY_SET_REPLACED','authority_set',p_case_code,
    jsonb_build_object(
      'case_code',p_case_code,
      'reason',trim(p_reason),
      'old_record_ids',to_jsonb(old_ids),
      'case_canon',p_case_canon_authority_id,
      'case_logic',p_case_logic_authority_id,
      'production_state',p_production_state_authority_id
    )
  );

  return jsonb_build_object(
    'case_code',p_case_code,
    'superseded_record_ids',to_jsonb(old_ids),
    'records',(
      select jsonb_agg(to_jsonb(r) order by r.authority_type)
      from public.factory_authority_records r
      where r.id in (rc.id,rl.id,rp.id)
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.factory_validate_authority(p_authority_id text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.factory_authority_records%rowtype;
  d public.factory_documents%rowtype;
  g public.factory_gate_records%rowtype;
begin
  select * into r from public.factory_authority_records where authority_id=p_authority_id for update;
  if not found then raise exception 'AUTHORITY_NOT_FOUND'; end if;
  if r.state <> 'staged' then raise exception 'AUTHORITY_NOT_STAGED'; end if;
  if r.source_document_key is null then raise exception 'SOURCE_DOCUMENT_REQUIRED'; end if;
  select * into d from public.factory_documents where document_key=r.source_document_key;
  if not found or d.case_code is distinct from r.case_code or d.sha256 is distinct from r.sha256 then raise exception 'SOURCE_DOCUMENT_MISMATCH'; end if;
  if r.supporting_gate_id is not null then
    select * into g from public.factory_gate_records where gate_id=r.supporting_gate_id;
    if not found or g.case_code is distinct from r.case_code or g.status <> 'pass' then raise exception 'SUPPORTING_GATE_NOT_PASS'; end if;
  end if;
  update public.factory_authority_records set state='validated',validated_by=p_actor,validated_at=now() where id=r.id returning * into r;
  update public.factory_documents set authority_state='validated',updated_at=now() where document_key=r.source_document_key and is_authoritative=false;
  insert into public.factory_audit_log(actor,action,entity_type,entity_id,payload)
  values(p_actor,'AUTHORITY_VALIDATED','authority_record',r.id::text,jsonb_build_object('authority_id',r.authority_id,'case_code',r.case_code,'authority_type',r.authority_type,'sha256',r.sha256));
  return to_jsonb(r);
end;
$function$
